import { describe as _describe, it as _it, test as _test, before, after, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';

export const describe = _describe;
export const it = _it;
export const test = _test;

it.each = function (cases) {
  return function (title, fn) {
    for (const c of cases) {
      const formattedTitle = title.replace(/%s|%d|%j|\$([a-zA-Z0-9_]+)/g, (match) => {
        if (typeof c === 'object' && c !== null) return JSON.stringify(c);
        return String(c);
      });
      it(formattedTitle, async () => {
        if (Array.isArray(c)) await fn(...c);
        else await fn(c);
      });
    }
  };
};

describe.each = function (cases) {
  return function (title, fn) {
    for (const c of cases) {
      describe(title, () => {
        if (Array.isArray(c)) fn(...c);
        else fn(c);
      });
    }
  };
};

export const beforeAll = before;
export const afterAll = after;
export { before, after, beforeEach, afterEach };

function formatMsg(custom, standard) {
  return custom ? `${custom}: ${standard}` : standard;
}

function matchesObject(target, expected) {
  if (target === expected) return true;
  if (!target || typeof target !== 'object') return false;
  if (!expected || typeof expected !== 'object') return false;
  for (const key of Object.keys(expected)) {
    if (!(key in target)) return false;
    const expVal = expected[key];
    const actVal = target[key];
    if (typeof expVal === 'object' && expVal !== null) {
      if (!matchesObject(actVal, expVal)) return false;
    } else if (actVal !== expVal) {
      return false;
    }
  }
  return true;
}

export function expect(actual, customMessage) {
  function matchers(target, isNot) {
    return {
      get not() {
        return matchers(target, !isNot);
      },
      get rejects() {
        return {
          toThrow(expected) {
            return (async () => {
              try {
                await target;
                assert.fail(formatMsg(customMessage, 'Expected promise to reject but it resolved'));
              } catch (err) {
                if (expected instanceof RegExp) {
                  assert.match(err.message, expected, customMessage);
                } else if (typeof expected === 'string') {
                  assert.ok(err.message.includes(expected), formatMsg(customMessage, `Expected ${err.message} to include ${expected}`));
                } else if (expected) {
                  assert.ok(err instanceof expected, formatMsg(customMessage, `Expected error instanceof ${expected.name}`));
                }
              }
            })();
          },
          toBeTruthy() {
            return (async () => {
              try {
                await target;
                assert.fail(formatMsg(customMessage, 'Expected promise to reject but it resolved'));
              } catch (err) {
                assert.ok(!!err, customMessage);
              }
            })();
          },
          toBeDefined() {
            return (async () => {
              try {
                await target;
                assert.fail(formatMsg(customMessage, 'Expected promise to reject but it resolved'));
              } catch (err) {
                assert.notStrictEqual(err, undefined, customMessage);
              }
            })();
          }
        };
      },
      get resolves() {
        return {
          toBe(expected) {
            return (async () => {
              const res = await target;
              if (isNot) assert.notStrictEqual(res, expected, customMessage);
              else assert.strictEqual(res, expected, customMessage);
            })();
          },
          toEqual(expected) {
            return (async () => {
              const res = await target;
              if (isNot) assert.notDeepStrictEqual(res, expected, customMessage);
              else assert.deepStrictEqual(res, expected, customMessage);
            })();
          },
          toBeDefined() {
            return (async () => {
              const res = await target;
              if (isNot) assert.strictEqual(res, undefined, customMessage);
              else assert.notStrictEqual(res, undefined, customMessage);
            })();
          },
          toBeTruthy() {
            return (async () => {
              const res = await target;
              if (isNot) assert.ok(!res, customMessage);
              else assert.ok(!!res, customMessage);
            })();
          }
        };
      },
      toBe(expected) {
        if (isNot) assert.notStrictEqual(target, expected, customMessage);
        else assert.strictEqual(target, expected, customMessage);
      },
      toEqual(expected) {
        if (isNot) assert.notDeepStrictEqual(target, expected, customMessage);
        else assert.deepStrictEqual(target, expected, customMessage);
      },
      toStrictEqual(expected) {
        if (isNot) assert.notDeepStrictEqual(target, expected, customMessage);
        else assert.deepStrictEqual(target, expected, customMessage);
      },
      toMatchObject(expected) {
        const pass = matchesObject(target, expected);
        if (isNot) assert.ok(!pass, formatMsg(customMessage, `Expected object not to match ${JSON.stringify(expected)}`));
        else assert.ok(pass, formatMsg(customMessage, `Expected object ${JSON.stringify(target)} to match ${JSON.stringify(expected)}`));
      },
      toHaveProperty(prop, value) {
        const has = target && typeof target === 'object' && (prop in target);
        if (isNot) {
          assert.ok(!has, formatMsg(customMessage, `Expected object not to have property ${prop}`));
        } else {
          assert.ok(has, formatMsg(customMessage, `Expected object to have property ${prop}`));
          if (arguments.length > 1) {
            assert.deepStrictEqual(target[prop], value, customMessage);
          }
        }
      },
      toBeTruthy() {
        if (isNot) assert.ok(!target, customMessage);
        else assert.ok(!!target, customMessage);
      },
      toBeFalsy() {
        if (isNot) assert.ok(!!target, customMessage);
        else assert.ok(!target, customMessage);
      },
      toBeNull() {
        if (isNot) assert.notStrictEqual(target, null, customMessage);
        else assert.strictEqual(target, null, customMessage);
      },
      toBeUndefined() {
        if (isNot) assert.notStrictEqual(target, undefined, customMessage);
        else assert.strictEqual(target, undefined, customMessage);
      },
      toBeDefined() {
        if (isNot) assert.strictEqual(target, undefined, customMessage);
        else assert.notStrictEqual(target, undefined, customMessage);
      },
      toContain(item) {
        if (typeof target === 'string') {
          if (isNot) assert.ok(!target.includes(item), formatMsg(customMessage, `Expected string not to contain "${item}"`));
          else assert.ok(target.includes(item), formatMsg(customMessage, `Expected string to contain "${item}"`));
        } else if (Array.isArray(target) || target instanceof Set) {
          const has = Array.isArray(target) ? target.includes(item) : target.has(item);
          if (isNot) assert.ok(!has, formatMsg(customMessage, `Expected collection not to contain ${JSON.stringify(item)}`));
          else assert.ok(has, formatMsg(customMessage, `Expected collection to contain ${JSON.stringify(item)}`));
        } else if (target && typeof target === 'object') {
          if (isNot) assert.ok(!(item in target), formatMsg(customMessage, `Expected object not to contain key ${item}`));
          else assert.ok(item in target, formatMsg(customMessage, `Expected object to contain key ${item}`));
        } else {
          assert.fail('toContain applied to invalid target');
        }
      },
      toHaveLength(len) {
        const actualLen = target ? target.length : undefined;
        if (isNot) assert.notStrictEqual(actualLen, len, customMessage);
        else assert.strictEqual(actualLen, len, customMessage);
      },
      toBeGreaterThan(val) {
        if (isNot) assert.ok(target <= val, formatMsg(customMessage, `Expected ${target} <= ${val}`));
        else assert.ok(target > val, formatMsg(customMessage, `Expected ${target} > ${val}`));
      },
      toBeGreaterThanOrEqual(val) {
        if (isNot) assert.ok(target < val, formatMsg(customMessage, `Expected ${target} < ${val}`));
        else assert.ok(target >= val, formatMsg(customMessage, `Expected ${target} >= ${val}`));
      },
      toBeLessThan(val) {
        if (isNot) assert.ok(target >= val, formatMsg(customMessage, `Expected ${target} >= ${val}`));
        else assert.ok(target < val, formatMsg(customMessage, `Expected ${target} < ${val}`));
      },
      toBeLessThanOrEqual(val) {
        if (isNot) assert.ok(target > val, formatMsg(customMessage, `Expected ${target} > ${val}`));
        else assert.ok(target <= val, formatMsg(customMessage, `Expected ${target} <= ${val}`));
      },
      toBeCloseTo(val, precision = 2) {
        const diff = Math.abs(target - val);
        const pass = diff < Math.pow(10, -precision) / 2;
        if (isNot) assert.ok(!pass, formatMsg(customMessage, `Expected ${target} not close to ${val}`));
        else assert.ok(pass, formatMsg(customMessage, `Expected ${target} close to ${val}`));
      },
      toMatch(pattern) {
        if (isNot) {
          if (pattern instanceof RegExp) assert.ok(!pattern.test(target), formatMsg(customMessage, `Expected ${target} not to match ${pattern}`));
          else assert.ok(!String(target).includes(pattern), formatMsg(customMessage, `Expected ${target} not to include ${pattern}`));
        } else {
          if (pattern instanceof RegExp) assert.match(String(target), pattern, customMessage);
          else assert.ok(String(target).includes(pattern), formatMsg(customMessage, `Expected ${target} to include ${pattern}`));
        }
      },
      toThrow(expected) {
        if (typeof target !== 'function') assert.fail('toThrow must be called on a function');
        if (isNot) {
          assert.doesNotThrow(target, customMessage);
        } else {
          if (expected instanceof RegExp) {
            assert.throws(target, expected, customMessage);
          } else if (typeof expected === 'string') {
            assert.throws(target, (err) => err.message.includes(expected), customMessage);
          } else if (expected) {
            assert.throws(target, expected, customMessage);
          } else {
            assert.throws(target, customMessage);
          }
        }
      }
    };
  }

  return matchers(actual, false);
}

let origDateNow = Date.now;
let origDate = globalThis.Date;
let fakeTime = null;

export const vi = {
  fn: (impl) => {
    const f = (...args) => {
      f.mock.calls.push(args);
      if (impl) return impl(...args);
    };
    f.mock = { calls: [] };
    return f;
  },
  spyOn: (obj, method) => {
    const orig = obj[method];
    const mock = vi.fn(orig);
    obj[method] = mock;
    mock.mockRestore = () => { obj[method] = orig; };
    return mock;
  },
  useFakeTimers: () => {
    fakeTime = Date.now();
  },
  useRealTimers: () => {
    fakeTime = null;
  },
  setSystemTime: (t) => {
    fakeTime = typeof t === 'number' ? t : new Date(t).getTime();
  },
  advanceTimersByTime: (ms) => {
    if (fakeTime !== null) fakeTime += ms;
  }
};
